mapper.select:
SELECT ir.user_id, ir.invest_name, tp.project_type, u.mobile, tp.invest_name, tp.abbreviation, ir.order_id, ir.project_id, ir.order_date, ir.profit_date expirationTime, ir.investment_amount actualAmount, ir.invest_count, u.biaoqian, u.username, u.agent, u.salesmanid, salesman_user.username as salesmanName, u.superior_name as supmobile, u.liebian FROM tb_investment_record ir LEFT JOIN tb_project tp ON ir.project_id = tp.invest_id LEFT JOIN tb_user u ON ir.user_id = u.id LEFT JOIN sys_user salesman_user ON u.salesmanid = salesman_user.id
AND tp.abbreviation LIKE CONCAT('%', #{params.abbreviation}, '%')
AND u.agent = #{params.agent}
AND u.salesmanid = #{params.salesmanid}
AND ir.status = #{params.status}
AND ir.user_id = #{params.userId}
AND ir.order_date >= FROM_UNIXTIME(#{params.startTime} / 1000)
AND ir.order_date <= FROM_UNIXTIME(#{params.endTime} / 1000)
AND u.biaoqian = #{params.biaoqian}
AND u.biaoqian IS NOT NULL AND u.biaoqian != ''
AND (u.biaoqian IS NULL OR u.biaoqian = '')
AND u.superior_name IS NOT NULL AND u.superior_name != ''
AND (u.superior_name IS NULL OR u.superior_name = '')
AND u.mobile LIKE CONCAT('%', #{params.mobile}, '%')
AND u.agent = #{params.currentUserId}
AND u.salesmanid = #{params.currentUserId}
ORDER BY ir.${params.orderField} ${params.order}
ORDER BY ir.order_date DESC
